import 'package:flutter/material.dart';
import '../core/services/api_client.dart';

class ProductDetailScreen extends StatefulWidget { final int productId; final void Function(Map<String,dynamic>) onAdd; const ProductDetailScreen({super.key,required this.productId,required this.onAdd}); @override State<ProductDetailScreen> createState()=>_ProductState(); }
class _ProductState extends State<ProductDetailScreen>{Map<String,dynamic>? p;List<int> options=[];int qty=1;bool loading=true;String? error;
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{try{final r=await ApiClient.get('/products/${widget.productId}');p=Map<String,dynamic>.from(r);}catch(e){error=e.toString();}if(mounted)setState(()=>loading=false);}
 @override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(error!=null)return Scaffold(appBar:AppBar(),body:Center(child:Text(error!)));final opts=(p!['options']??[]) as List;final price=(double.tryParse('${p!['base_price']}')??0);return Scaffold(appBar:AppBar(title:Text(p!['name']??'Product')),body:ListView(padding:const EdgeInsets.all(18),children:[Container(height:190,decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),gradient:const LinearGradient(colors:[Color(0xFFAFDDE5),Color(0xFFDDF5F5)])),child:const Icon(Icons.fastfood_rounded,size:90,color:Color(0xFF003135))),const SizedBox(height:18),Text(p!['name']??'',style:const TextStyle(fontSize:27,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text(p!['description']??'No description available.'),const SizedBox(height:20),if(opts.isNotEmpty)const Text('Add-ons',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),...opts.map((o){final id=o['id'] as int;return CheckboxListTile(value:options.contains(id),onChanged:(v)=>setState(()=>v==true?options.add(id):options.remove(id)),title:Text(o['name']??''),subtitle:Text('+ ₱${o['price']}'),contentPadding:EdgeInsets.zero);}),const SizedBox(height:12),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Quantity',style:TextStyle(fontWeight:FontWeight.w800)),Row(children:[IconButton(onPressed:qty>1?()=>setState(()=>qty--):null,icon:const Icon(Icons.remove_circle_outline)),Text('$qty',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w800)),IconButton(onPressed:()=>setState(()=>qty++),icon:const Icon(Icons.add_circle_outline))])]),const SizedBox(height:16),FilledButton.icon(onPressed:()=>widget.onAdd({'product_id':p!['id'],'name':p!['name'],'unit_price':price,'quantity':qty,'options':options}),icon:const Icon(Icons.add_shopping_cart),label:Text('Add to cart • ₱${price.toStringAsFixed(2)}'))]));}
}
